import {physicalBindings,physicalState} from './physical-lore.js?v=5.16.0';
export const COMBAT_RELICS=[
 {id:'stormcoil',name:'Stormcoil Amber',chapter:2,source:'brake-lantern',color:'#f2d16c',glyph:'ϟ',effect:'Volt on a wet target arcs to one nearby enemy; rain and conductive rooms can also feed the arc.',lore:'The brakekeeper’s signal condensed a season of storms into a single copper seam.'},
 {id:'graftroot',name:'Graftroot Seed',chapter:7,source:'graft-sleeve',color:'#9bd6a8',glyph:'❋',effect:'Mend and healing supplies turn half of otherwise wasted healing into a shield, up to 80 per action.',lore:'A seed from the living graft. It remembers how to grow without borrowing a voice.'},
 {id:'kilnglaze',name:'Kilnheart Glaze',chapter:8,source:'crown-shard',color:'#efac7e',glyph:'◈',effect:'Your glazed shield resists more heat; your Earth and physical strikes shatter enemy glaze more strongly.',lore:'A cooled fragment from an isolated furnace, reclaimed after its command circuit was broken.'},
 {id:'riverglass',name:'Riverglass Pearl',chapter:11,source:'river-measure',color:'#8dd7e1',glyph:'≈',effect:'Making steam gives nearby allies a 25-point shield. Steam consumes its heat or water setup.',lore:'An unfiled measurement ring held a pearl below the flood line.'},
 {id:'frostline',name:'Frostline Needle',chapter:12,source:'blank-nameplate',color:'#bcdef2',glyph:'✧',effect:'A physical or Earth hit on a brittle enemy breaks more armor and deals a larger single impact.',lore:'A sliver preserved behind an unnumbered plate; its edge follows a natural crystal fault.'},
 {id:'bellrest',name:'Bellrest Prism',chapter:16,source:'bell-fork',color:'#cbb8e6',glyph:'◉',effect:'An Echo cast while guarded consumes that guard to strengthen its one delayed answer.',lore:'Two registers meet inside the prism, separated by a visible seam of silence.'},
 {id:'witnessopal',name:'Witness Opal',chapter:20,source:'witness-seal',color:'#c7a8da',glyph:'◇',effect:'Shade on an exposed enemy sends one bounded echo of the impact to a nearby enemy.',lore:'The uncut witness strip left a dark mineral impression that cannot be polished into a cleaner story.'},
 {id:'dawnspindle',name:'Dawnspindle',chapter:24,source:'empty-reed',color:'#eddb9e',glyph:'✺',effect:'Link with a shielded partner trades some shield for a shared guard and lower strain.',lore:'The answering circle leaves an opening; the spindle holds the space between cooperating voices.'}
];
export function relicState(s){const p=s.combatRelics??={version:1,owned:[],claimed:[]};p.owned??=[];p.claimed??=[];return p;}
export function equippedRelics(hero){return [...new Set((hero?.battleRelics||[]).filter(id=>COMBAT_RELICS.some(r=>r.id===id)))].slice(0,2);}
export function equipCombatRelic(s,heroId,id,slot=0){if(s.mode==='battle'||!s.recruited.includes(heroId)||![0,1].includes(slot)||!relicState(s).owned.includes(id))return false;for(const h of s.heroes)if(h.id!==heroId&&equippedRelics(h).includes(id))return false;const h=s.heroes[heroId],slots=[...(h.battleRelics||[])];if(slots.includes(id))return false;slots[slot]=id;h.battleRelics=slots.slice(0,2);return true;}
export function unequipCombatRelic(s,id,slot){if(s.mode==='battle'||!s.recruited.includes(id)||![0,1].includes(slot))return false;const h=s.heroes[id];h.battleRelics??=[];h.battleRelics[slot]=null;return true;}
export function relicObjects(w){const p=relicState(w.state),physical=physicalState(w.state),bindings=physicalBindings(w);return COMBAT_RELICS.filter(r=>r.chapter<=w.state.chapter&&physical.claimed.includes(r.source)&&!p.claimed.includes(r.id)).flatMap(r=>{const site=bindings.find(o=>o.physicalId===r.source&&o.physicalRole==='reward'&&o.physicalLocation===w.state.scene);return site?[{type:'combat-relic',battleRelic:r.id,xy:site.xy,label:'Recover rare '+r.name}]:[];});}
export function collectCombatRelic(w,o){if(!o?.battleRelic)return false;const r=COMBAT_RELICS.find(r=>r.id===o.battleRelic),p=relicState(w.state),actual=relicObjects(w).find(v=>v.battleRelic===o.battleRelic);if(!r||!actual||Math.hypot(w.state.x-actual.xy[0]-.5,w.state.y-actual.xy[1]-.5)>2.05)return true;if(p.claimed.includes(r.id))return true;p.claimed.push(r.id);if(!p.owned.includes(r.id))p.owned.push(r.id);const entry={id:'combat-relic:'+r.id,title:'Rare relic · '+r.name,text:r.lore+' '+r.effect,chapter:w.state.chapter};if(w.state.story?.journal&&!w.state.story.journal.some(e=>e.id===entry.id))w.state.story.journal.push(entry);w.notice('Rare collectible: '+r.name+' · Equip it in Battle relics.');w.callbacks.onMusic('instrument:discovery');return true;}
export function drawCombatRelic(c,id,x,y,t,T=48){const r=COMBAT_RELICS.find(r=>r.id===id);if(!r)return;c.save();c.translate(x*T,y*T-28+Math.sin(t*2)*2);const glow=c.createRadialGradient(0,0,0,0,0,34);glow.addColorStop(0,r.color+'77');glow.addColorStop(1,r.color+'00');c.fillStyle=glow;c.fillRect(-34,-34,68,68);c.strokeStyle=r.color;c.lineWidth=2;c.beginPath();c.ellipse(0,17,20,6,0,0,Math.PI*2);c.stroke();c.fillStyle=r.color;c.beginPath();c.moveTo(0,-22);c.lineTo(15,-6);c.lineTo(10,12);c.lineTo(0,20);c.lineTo(-10,12);c.lineTo(-15,-6);c.closePath();c.fill();c.fillStyle='#fff8';c.beginPath();c.moveTo(0,-22);c.lineTo(0,2);c.lineTo(-15,-6);c.closePath();c.fill();c.fillStyle='#172e3c';c.font='bold 15px serif';c.textAlign='center';c.fillText(r.glyph,0,7);c.restore();}
